def clone_record(value):
    if isinstance(value, dict):
        return {key: clone_record(item) for key, item in value.items()}
    if isinstance(value, list):
        return [clone_record(item) for item in value]
    return value

class TenantResults:
    def __init__(self):
        self.rows = {}
    def append(self, tenant, result):
        if not isinstance(tenant, str) or not tenant:
            raise ValueError('tenant required')
        self.rows.setdefault(tenant, []).append(result)
        return self.snapshot(tenant)
    def snapshot(self, tenant):
        if not isinstance(tenant, str) or not tenant:
            raise ValueError('tenant required')
        return clone_record(self.rows.get(tenant, []))
